import json
with open('DATA/products/PersonalizeForce.json') as f:
    d = json.load(f)
# Get all users providing insights on competitor products (TailorAI, PersonaAI, SmartSuggest)
relevant = {}
for i, msg in enumerate(d['slack']):
    text = msg['Message']['User'].get('text', '')
    if not text:
        continue
    tl = text.lower()
    # Substantive insights on strengths/weaknesses
    keywords = ['tailorai', 'personaai', 'smartsuggest']
    for kw in keywords:
        if kw in tl:
            # Check for strength/weakness/insight words
            insight_words = ['weakness', 'strength', 'insight', 'challenge', 'issue', 'barrier', 'struggle', 'gaining traction', 'read about', 'rely on', 'dependency', 'learning curve', 'complex', 'high initial', 'real-time', 'multi-channel', 'algorithm', 'integrate', 'feature', 'expensive', 'struggle']
            if any(w in tl for w in insight_words):
                uid = msg['Message']['User']['userId']
                if uid not in relevant:
                    relevant[uid] = []
                relevant[uid].append((i, msg['Channel']['name'], text[:200]))
            break

for uid, msgs in relevant.items():
    print(f'=== {uid} ===')
    for m in msgs:
        print(f'  [{m[0]}] {m[1]}: {m[2]}')
    print()
"

